import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"ADR-0070: Refinement Inference Scope — Deterministic Dataflow","description":"","frontmatter":{},"headers":[],"relativePath":"handl/project/adrs/0070-refinement-inference-scope.md","filePath":"vendored/handl/project/adrs/0070-refinement-inference-scope.md"}`),a={name:`handl/project/adrs/0070-refinement-inference-scope.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0070-refinement-inference-scope-—-deterministic-dataflow" tabindex="-1">ADR-0070: Refinement Inference Scope — Deterministic Dataflow <a class="header-anchor" href="#adr-0070-refinement-inference-scope-—-deterministic-dataflow" aria-label="Permalink to “ADR-0070: Refinement Inference Scope — Deterministic Dataflow”">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><p>Accepted</p><p>Builds on <a href="./0068-predicates-as-types.html">ADR-0068 — Predicates as Types</a>, <a href="./0069-arrow-native-modules.html">ADR-0069 — Arrow-Native Modules</a>, and the refinement inference engine in <code>crates/plugin-ext-refinement/</code>.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The refinement inference engine (<code>plugin-ext-refinement</code>) derives semantic guarantees from arrow graph structure with zero user annotations. It works by:</p><ol><li>Reading the graph (which combinators are wired together)</li><li>Looking up axioms (what the leaf atoms guarantee)</li><li>Composing (Seq conjoins, First preserves side-channel, Choice branches, Loop finds fixpoint)</li><li>Checking implications (can we prove guarantee ⟹ postcondition?)</li></ol><p>This is deterministic structural derivation — no search, no heuristics, no machine learning. The graph IS the proof.</p><p>The question: <strong>what kinds of programs does this work for?</strong></p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>The inference mechanism applies to <strong>deterministic dataflow</strong> — programs where the graph structure fully determines the behavior. This is the scope boundary for the current architecture.</p><h3 id="in-scope" tabindex="-1">In scope <a class="header-anchor" href="#in-scope" aria-label="Permalink to “In scope”">​</a></h3><ul><li><strong>List operations</strong>: sort, map, filter, fold, insert, take, drop, zip, scan, reduce. Proven: 16 arrows, all inferred with zero annotations.</li><li><strong>Parsers (recursive descent, no backtracking)</strong>: Pratt parsing, token consumption, precedence climbing. Proven: 1 arrow (Pratt parser), infers LengthSubOne (tokens consumed) and Nested ListLength (terminates).</li><li><strong>State machines (data invariants)</strong>: counters, bounded buffers, protocol states. The state machine is a loop over event handlers; the fixpoint discovers data invariants like Count ≥ 0.</li></ul><h3 id="out-of-scope-current-architecture" tabindex="-1">Out of scope (current architecture) <a class="header-anchor" href="#out-of-scope-current-architecture" aria-label="Permalink to “Out of scope (current architecture)”">​</a></h3><ul><li><strong>Parsers with backtracking</strong>: need failure as a first-class effect. The current Choice combinator doesn&#39;t model failure propagation. See ADR-0071.</li><li><strong>Concurrent systems</strong>: need non-deterministic scheduling and synchronization. Arrows are deterministic dataflow. See ADR-0072.</li><li><strong>Non-deterministic computation</strong>: the inference assumes the graph structure determines the output. Non-determinism breaks this.</li></ul><h3 id="why-this-boundary" tabindex="-1">Why this boundary <a class="header-anchor" href="#why-this-boundary" aria-label="Permalink to “Why this boundary”">​</a></h3><p>The inference reads the proof off the graph structure. This requires that the graph structure fully determines the program&#39;s behavior. If the behavior depends on factors not visible in the graph (scheduling, failure, external state), the inference cannot see them.</p><p>The good news: deterministic dataflow covers most business logic, most data transformation, and most algorithms. The cases that don&#39;t fit (concurrency, backtracking) are exactly where traditional verification also struggles.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to “Positive”">​</a></h3><ul><li>Clear scope: the inference engine targets deterministic dataflow.</li><li>Proven results: 17+ arrows across 3 domains (lists, parsers, state machines), all inferred with zero annotations.</li><li>Compositional: contracts flow through imports (ADR-0069).</li><li>The boundary is honest — we don&#39;t claim to handle what we can&#39;t.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to “Negative”">​</a></h3><ul><li>Concurrency, backtracking, and non-determinism are excluded.</li><li>Users working in those domains need different verification approaches.</li><li>Extending to those domains requires new arrow calculus extensions, not just new axioms.</li></ul><h2 id="related-adrs" tabindex="-1">Related ADRs <a class="header-anchor" href="#related-adrs" aria-label="Permalink to “Related ADRs”">​</a></h2><ul><li><a href="./0068-predicates-as-types.html">ADR-0068 — Predicates as Types</a></li><li><a href="./0069-arrow-native-modules.html">ADR-0069 — Arrow-Native Modules</a></li><li><a href="./0071-failure-tracking-arrows.html">ADR-0071 — Failure-Tracking Arrows for Backtracking Parsers</a></li><li><a href="./0072-concurrent-arrow-calculus.html">ADR-0072 — Concurrent Arrow Calculus</a></li><li><a href="./0073-state-machine-invariants.html">ADR-0073 — State Machine Invariants via Fixpoint Discovery</a></li></ul>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};